"""Render the static IPO dashboard."""
import html
from datetime import date


def render_site(records):
    today = date.today()
    def is_open(r):
        start, end = r.get('open_date'), r.get('close_date')
        return bool(start and end and start <= today <= end)
    opened = [r for r in records if is_open(r)]
    others = [r for r in records if not is_open(r)]
    def fmt(d):
        return d.strftime('%d %b') if d else '—'
    def table(group, selectable):
        rows = []
        for r in group:
            name = html.escape(r['name'])
            pct = r.get('gmp_pct')
            gmp = f'{pct:+.2f}%' if pct is not None else '—'
            action = f'<button class="choose" data-name="{name}">Analyze</button>' if selectable else ''
            rows.append(f'<tr><td>{name}</td><td class="green">{gmp}</td><td>{html.escape(str(r.get("price") or "—"))}</td><td>{html.escape(str(r.get("issue_size") or "—"))}</td><td>{fmt(r.get("open_date"))} – {fmt(r.get("close_date"))}</td><td>{fmt(r.get("listing_date"))}</td><td>{action}</td></tr>')
        return '<div class="scroll"><table><thead><tr><th>Company</th><th>GMP</th><th>Price (₹)</th><th>Issue Size</th><th>Open – Close</th><th>Listing</th><th></th></tr></thead><tbody>' + (''.join(rows) or '<tr><td colspan="7">No IPOs in this view.</td></tr>') + '</tbody></table></div>'
    options = ''.join(f'<option value="{html.escape(r["name"])}">{html.escape(r["name"])}</option>' for r in opened)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>IPO Dashboard</title>
<style>
:root{{color-scheme:dark;font-family:Inter,Segoe UI,Arial,sans-serif;background:#090e25;color:#f5f4ff}}*{{box-sizing:border-box}}body{{margin:0 auto;padding:20px;max-width:1500px;background:radial-gradient(circle at 50% 0,#222d58,transparent 60%)}}h1{{margin:0;font-size:2rem}}h2{{margin:0 0 20px;font-size:1.4rem}}h3{{margin:0 0 15px}}p{{color:#c4c8e0;margin:6px 0 0}}.top,.score-grid,.detail-grid{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.panel,.analysis{{background:linear-gradient(135deg,#171e40,#10152f);border:1px solid #545c9b;border-radius:15px;padding:20px;box-shadow:0 12px 35px #03071466}}button,.button{{display:inline-block;background:#42337e;color:#fff;border:1px solid #8876db;border-radius:9px;padding:10px 14px;cursor:pointer;font:inherit;text-decoration:none}}button:hover,.button:hover,button.active{{background:#6145aa}}.refresh{{float:right;font-size:.8rem}}.tabs{{display:flex;gap:8px;margin:18px 0 8px}}.scroll{{overflow-x:auto}}table{{border-collapse:collapse;width:100%;font-size:.85rem}}th,td{{padding:11px 8px;text-align:left;border-bottom:1px solid #303957;white-space:nowrap}}th{{font-weight:500;color:#d0d2e6}}.green{{color:#4ae485;font-weight:700}}.choose{{padding:5px 8px;font-size:.75rem}}.upload-box{{background:linear-gradient(110deg,#ded5ff,#aa91ef);border-radius:13px;padding:20px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#14142c}}.upload-box p{{color:#282441;font-size:.85rem}}#upload{{display:none}}select{{background:#20264c;border:1px solid #7771c7;color:white;padding:9px;border-radius:7px;margin-top:8px;max-width:100%}}.hint,.status,.updated{{font-size:.82rem;color:#b6bad6;margin-top:12px}}.status{{min-height:1.2em}}.analysis{{margin-top:14px}}.analysis-head{{display:flex;justify-content:space-between;gap:10px;margin-bottom:15px}}.analysis-head span{{font-size:.85rem}}.score-grid>div,.detail-grid>section{{border:1px solid #454d82;border-radius:12px;padding:20px;background:#151c3b}}.verdict{{background:linear-gradient(110deg,#155038,#11263b)!important;display:flex;flex-direction:column;justify-content:center}}.verdict strong{{font-size:3rem;text-transform:uppercase;color:#5cf18c}}.verdict.avoid strong{{color:#ff8585}}.verdict.watchlist strong{{color:#ffd66b}}.pillar{{display:grid;grid-template-columns:170px 1fr 35px;gap:10px;align-items:center;margin:8px 0;font-size:.83rem}}.pillar small{{display:block;color:#abb0d1}}.track{{height:12px;border-radius:20px;background:#333b60;overflow:hidden}}.track span{{display:block;height:100%;border-radius:20px;background:linear-gradient(90deg,#48e683,#a5eb69)}}.detail-grid{{margin-top:14px}}.detail-grid section{{overflow:auto}}.warning{{color:#ffd66b}}@media(max-width:850px){{.top,.score-grid,.detail-grid{{grid-template-columns:1fr}}.upload-box{{flex-wrap:wrap}}.pillar{{grid-template-columns:140px 1fr 30px}}}}
</style></head><body><div class="top"><section class="panel"><a class="button refresh" href="https://github.com/Tushar-Mishra999/ipo-bot/actions/workflows/ipo-bot.yml" target="_blank" rel="noopener">↻ Manual refresh</a><h1>IPO Dashboard</h1><p>Track mainboard IPOs with key financials.</p><div class="tabs"><button id="open-tab" class="active">Open IPOs ({len(opened)})</button><button id="recent-tab">Upcoming / Recently Closed ({len(others)})</button></div><div id="open-list">{table(opened, True)}</div><div id="recent-list" hidden>{table(others, False)}</div><div class="updated">Last updated {today.strftime('%d %B %Y')}. Manual refresh opens GitHub Actions. Select Run workflow there.</div></section><section class="panel"><h2>Analyze an IPO in Depth</h2><div class="upload-box"><div><strong>Upload Company Financials (Screener.in Excel)</strong><p>Uses available annual data from the Data Sheet tab</p></div><label class="button" for="upload">↑ Upload Excel</label><input id="upload" type="file" accept=".xlsx,.xls"></div><label class="hint" for="company">Company to analyze</label><br><select id="company"><option value="">Choose a company</option>{options}</select><div class="hint">Use Export to Excel on Screener.in. Analysis runs in your browser.</div><div id="upload-status" class="status" role="status"></div></section></div><section id="analysis" class="analysis" hidden></section><script src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js"></script><script src="analysis.js"></script><script>
for(const [button,list,otherButton,otherList] of [['open-tab','open-list','recent-tab','recent-list'],['recent-tab','recent-list','open-tab','open-list']])document.getElementById(button).addEventListener('click',()=>{{document.getElementById(list).hidden=false;document.getElementById(otherList).hidden=true;document.getElementById(button).classList.add('active');document.getElementById(otherButton).classList.remove('active')}});document.querySelectorAll('.choose').forEach(button=>button.addEventListener('click',()=>{{document.getElementById('company').value=button.dataset.name;document.getElementById('upload').click()}}));</script></body></html>'''
